{"explanation":"In flat (Euclidean) geometry, draw a line through the triangle’s top vertex parallel to its base. The two base angles reappear beside the top angle because parallel lines have equal alternate interior angles. Together, those three angles form a straight angle—180°. Drag the top vertex to see that the individual angles change, but their sum does not.","manimCode":"const heading = new Text({ text: 'Why triangle angles add to 180°', fontSize: 32, color: WHITE });
heading.moveTo([0, 3.15, 0]);
const hint = new Text({ text: 'Drag the yellow vertex • The upper line stays parallel to the base', fontSize: 19, color: GRAY });
hint.moveTo([0, 2.5, 0]);

const baseA = [-3, -1.5, 0];
const baseB = [3, -1.5, 0];
const apex = new Dot({ point: [-0.5, 1.25, 0], color: YELLOW });
const dotA = new Dot({ point: baseA, color: BLUE });
const dotB = new Dot({ point: baseB, color: ORANGE });
const triangleShape = new Polygon({ vertices: [baseA, baseB, apex.getCenter()], color: WHITE });
triangleShape.setStrokeWidth(2).setFill(BLUE, 0.07);
const parallelLine = new Polygon({ vertices: [[-4.4, 1.25, 0], [4.4, 1.25, 0]], color: GRAY });
parallelLine.setStrokeWidth(2).setFillOpacity(0);

function sectorPoints(center, startAngle, endAngle, radius) {
  const pts = [[...center]];
  for (let i = 0; i <= 30; i++) {
    const theta = startAngle + (endAngle - startAngle) * i / 30;
    pts.push([center[0] + radius * Math.cos(theta), center[1] + radius * Math.sin(theta), 0]);
  }
  pts.push([...center]);
  return pts;
}
function newSector(col) {
  const wedge = new Polygon({ vertices: sectorPoints([0, 0, 0], 0, 0.5, 0.5), color: col });
  wedge.setFill(col, 0.35).setStrokeWidth(1.5);
  return wedge;
}
const baseAlpha = newSector(BLUE);
const baseBeta = newSector(ORANGE);
const topAlpha = newSector(BLUE);
const topGamma = newSector(GREEN);
const topBeta = newSector(ORANGE);

function angleLabel(symbol, col) {
  return new Text({ text: symbol, fontSize: 24, color: col });
}
const labelA = angleLabel('α', BLUE);
const labelB = angleLabel('β', ORANGE);
const topLabelA = angleLabel('α', BLUE);
const topLabelG = angleLabel('γ', GREEN);
const topLabelB = angleLabel('β', ORANGE);
function placeLabel(label, center, angle, radius) {
  label.moveTo([center[0] + radius * Math.cos(angle), center[1] + radius * Math.sin(angle), 0]);
}
let angleReadout;
function rebuild() {
  const tip = apex.getCenter();
  const alpha = Math.atan2(tip[1] - baseA[1], tip[0] - baseA[0]);
  const beta = Math.atan2(tip[1] - baseB[1], baseB[0] - tip[0]);
  const gamma = Math.PI - alpha - beta;
  triangleShape.setVertices([baseA, baseB, tip]);
  parallelLine.setVertices([[-4.4, tip[1], 0], [4.4, tip[1], 0]]);
  baseAlpha.setVertices(sectorPoints(baseA, 0, alpha, 0.55));
  baseBeta.setVertices(sectorPoints(baseB, Math.PI - beta, Math.PI, 0.55));
  topAlpha.setVertices(sectorPoints(tip, Math.PI, Math.PI + alpha, 0.6));
  topGamma.setVertices(sectorPoints(tip, Math.PI + alpha, 2 * Math.PI - beta, 0.6));
  topBeta.setVertices(sectorPoints(tip, 2 * Math.PI - beta, 2 * Math.PI, 0.6));
  placeLabel(labelA, baseA, alpha / 2, 0.85);
  placeLabel(labelB, baseB, Math.PI - beta / 2, 0.85);
  placeLabel(topLabelA, tip, Math.PI + alpha / 2, 0.87);
  placeLabel(topLabelG, tip, Math.PI + alpha + gamma / 2, 0.87);
  placeLabel(topLabelB, tip, 2 * Math.PI - beta / 2, 0.87);
  if (angleReadout) scene.remove(angleReadout);
  const deg = v => (v * 180 / Math.PI).toFixed(1);
  angleReadout = new Text({ text: `α = ${deg(alpha)}°      β = ${deg(beta)}°      γ = ${deg(gamma)}°`, fontSize: 23, color: WHITE });
  angleReadout.moveTo([0, -2.55, 0]);
  scene.add(angleReadout);
}

scene.add(parallelLine, triangleShape, baseAlpha, baseBeta, topAlpha, topGamma, topBeta, labelA, labelB, topLabelA, topLabelG, topLabelB, dotA, dotB, apex);
rebuild();
makeDraggable(apex, scene, { constrainX: [-1.6, 1.6], constrainY: [0.25, 1.65], onDrag: () => rebuild() });

const sumFormula = new MathTex({ latex: '\\alpha + \\gamma + \\beta = 180^\\circ' });
await sumFormula.waitForRender();
sumFormula.moveTo([0, -3.15, 0]);
await scene.play(new AnimationGroup([new Write(heading), new FadeIn(hint), new Write(sumFormula)]));
await scene.wait(999999);"}

